from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(4,'english','one-thing-at-a-time','One Thing at a Time',
 ('Work when you work, play when you play','This old poem gives a simple rule: when you work, give your whole attention to the work, and when you play, play fully. Doing one thing at a time and doing it well is the way to be useful and happy. In this chapter you will read the poem, learn the words might, useful and moments, describe what people are doing, listen for silent letters, write your daily routine and solve riddles.'),
 [('The poem',['The poem says: work while you work and play while you play.','To be useful and happy, we should do everything with all our might, which means with all our strength and effort.','Things done by halves, which means only half done, are never done right.','The poem calls one thing at a time, done well, a very good rule that many people agree with.','It adds that moments should never be wasted, so we should use short bits of time wisely.','The message is to give your full attention to what you are doing right now.']),
  ('Why focus matters',['When you do one thing at a time, you finish faster and make fewer mistakes.','Focus helps you learn better. If you try to do many things together, you may do all of them badly.','After completing a task well, we feel proud, happy and relaxed.','Simple habits like deep breathing, yoga and a short walk can help us stay calm and focused.']),
  ('New words',['Might means strength or power. Useful means helpful or beneficial. Moments are short periods of time.','Use them in sentences: She pushed the door with all her might. A pencil is useful for writing. Do not waste your moments.']),
  ('Telling what people are doing',['To say what is happening now we use is or are with an action word ending in -ing.','Two girls are going to school. A woman is typing on a computer. A boy is reading a book.','Use is for one person and are for more than one. The structure is who, is or are, and the action.']),
  ('Silent letters',['Some words have a letter that we write but do not say.','In calm, palm, chalk, talk, calf and balm the l is silent. In leaf, jail, hall, clean, shelf, silk, plum and self we do hear the l.','Listen carefully to a word before you decide whether a letter is silent.']),
  ('My daily routine',['A routine is the list of things we do every day in order.','Mark each activity as work or play: studying is work, playing cricket is play.','Use a.m. for times before noon and p.m. for times after noon. I wake up at 6 a.m. and school ends at 3 p.m.','Write your routine as a paragraph: I begin my day at six a.m. I brush my teeth and then take a bath. After this I eat breakfast. Then I leave for school.']),
  ('Riddles',['Thirty white horses on a red hill that chomp and stomp and stand still are your teeth on your gums.','A tall lady in a white frock with a yellow face and a red nose, who gets shorter the longer she stands, is a candle.','Hard and brown outside, soft and white inside, is a coconut.','Riddles make us think before we answer, which is another way of focusing.'])],
 [('Write a sentence: a boy / read / book.',[('Decide who is acting: a boy.','One person, so we use is.'),('Add is and the action ending in -ing: is reading.','Is plus verb-ing shows what is happening now.'),('So: A boy is reading a book.','For two boys: Two boys are reading books.')]),
  ('Which word has a silent l: calm or leaf?',[('Say calm aloud.','We say kahm, no l sound.'),('Say leaf aloud.','We say leef, with an l sound.'),('So calm has a silent l.','Palm, chalk and talk also have a silent l.')])],
 ('Explain the rule of the poem and why doing one thing at a time helps.',['Work while you work','Play while you play','Do things with all your might','Things done by halves are never done right'],['Doing many things together is best','Play only matters']),
 ['Work while you work and play while you play.','Might means strength, useful means helpful, moments means short times.','Use is or are with an -ing word to say what is happening.','Some letters, like the l in calm, are silent.','A routine shows what we do and when, using a.m. and p.m.'],
 [M('1',1,'What does the poem advise?','Work while you work, play while you play',[('Work and play together','The poem says one at a time'),('Never play','Play is part of the rule')],'Give full attention to one thing.'),
  M('2',1,'Why is focusing on one thing at a time important?','You do it better and faster',[('You get more breaks','The reason is quality'),('You do not need to try','The poem says do your best')],'Focus helps you finish well.'),
  M('3',1,'What does might mean in the poem?','Strength',[('Maybe','Might here is strength'),('Night','Different word')],'Do it with all your strength.'),
  M('4',1,'What does useful mean?','Helpful',[('Colourful','Not the meaning'),('Heavy','Not the meaning')],'Useful means helpful.'),
  M('5',2,'What are moments?','Short periods of time',[('Long years','Moments are short'),('Big rooms','Not the meaning')],'Moments are very short bits of time.'),
  M('6',2,'Which word has a silent l?','Calm',[('Leaf','The l is heard'),('Hall','The l is heard')],'Calm sounds like kahm.'),
  M('7',2,'Which word has a silent l?','Chalk',[('Silk','The l is heard'),('Self','The l is heard')],'Chalk sounds like chawk.'),
  M('8',2,'Choose the correct sentence.','Two girls are going to school.',[('Two girls is going to school.','Two needs are'),('Two girl are going to school.','Girls needs an s')],'Two girls are going to school.'),
  M('9',2,'7 a.m. means ___.','seven in the morning',[('seven in the evening','That is p.m.'),('seven at midnight','Not the meaning')],'a.m. is before noon.'),
  M('10',2,'What is the answer: tall lady in a white frock who gets shorter as she stands?','A candle',[('A tree','A tree grows taller'),('A pencil','Not the riddle')],'A candle burns down and gets shorter.'),
  S('11',2,'What is hard and brown outside, soft and white inside?',['coconut','a coconut'],'A coconut has a hard shell and soft white flesh.'),
  F('12',3,'The poem says things done by halves are never done right.',True,'Half-done work is not done well.')],
 keep=['routine','might'])
